n = int(input())
dp = [0] * (n + 1)
dp[0] = 1
for i in range(1, n + 1):
    for step in (1, 2, 3):
        if i - step >= 0:
            dp[i] += dp[i - step]

print("Table:", dp)
print(f"Ways to climb {n} steps: {dp[n]}")

